//历史记录
function reportProcess(avid, cid) {
	const {java,cookie} = this;
    let csrf = cookie.getKey("https://www.bilibili.com","bili_jct");
    let url = "http://api.bilibili.com/x/v2/history/report";
    let body = "";
    if(cid){
       body = "aid="+avid+"&cid="+cid+"&csrf="+csrf+"&progress=0";
    }else{
        body = "aid="+avid+"&type=5&dt=2&csrf="+csrf
    }

    let headers = {
            Cookie: cookie.getCookie("https://www.bilibili.com")
     }

     url = url+","+JSON.stringify({
         "method":"POST",
         "body":body,
         "headers":headers
     })
    java.ajax(url)

}



