let script = `

setTimeout(function() {  
    ${getWbiEnc.toString().replace(/const \{java\}.*/,'')}
    let offset = "";
    let hotJson = ${java.base64Decode(hotu)};
    let newJson = ${java.base64Decode(newu)};
    let hoturl = "https://api.bilibili.com/x/v2/reply/wbi/main?"+getWbiEnc(hotJson);
    let newurl = "https://api.bilibili.com/x/v2/reply/wbi/main?"+getWbiEnc(newJson);

    let currentUrl = hoturl;    
    let isLoading = false;
    let isReplyLoading = false;


    let commentTotal = 0;
    var pageTotal = 1;

    let page = 1;
    let replyPage = 1;

    let hasMore = true;
    let hasReplyMore = true;
    let wrongi = 3;

    var replyapi = "";



    loadUrl();

    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.addEventListener('click', function() {
                let n = this.textContent;
                document.querySelectorAll('.tab-btn').forEach(x=>{
                    x.classList.remove('active');
                });

                commentTotal = 0;
                if(/热门/.test(n)){
                    currentUrl = hoturl
                }else if(/最新/.test(n)){
                    currentUrl = newurl
                }

                java.toast("加载中.....");

                loadUrl();
                this.classList.add('active');
            });
     });

function loadUrl(){
	let JsonData = getJson(currentUrl);
	let html = createCommentHtml(JsonData);
	document.querySelector('.comments-container').innerHTML = html;
	window.scrollTo(0, 0);
	let loader = document.querySelector(".loading-more");
	wrongi--;
	if(loader && wrongi>0){
		java.longToast("正在重试倒数第"+wrongi+"次....");
		loadUrl();
		loader.onclick = () => {
			java.longToast("正在重试....")
			loader.textContent = "加载中....";
			loadUrl();
		};
	}else{
		wrongi = 3;
	}
	openReply();
}

function openReply(){
        document.querySelectorAll('.load-more-replies,.close-more-replies')?document.querySelectorAll('.load-more-replies,.close-more-replies').forEach(btn => {
            btn.addEventListener('click', function(e) {
                   let className = this.className;
                   if(/load-more-replies/.test(className)){
                         let replyNum = this.dataset.num;
                         document.querySelector(".reply-title span").textContent = replyNum;
                         replyapi = "https://api.bilibili.com/x/v2/reply/reply?oid="+hotJson.oid+"&type="+hotJson.type+"&root="+this.dataset.id+"&ps=20&pn=1&web_location=333.788";
                         getReply()
                   }
            });
        }):null;
     }

function getReply(){
    let modalOverlay = document.querySelector("#modalOverlay");
    modalOverlay.classList.remove("hide");
    document.body.style.overflow = "hidden"

    modalOverlay.onclick = ()=>{
        modalOverlay.classList.add("hide");
        document.body.style.overflow = "auto";
        isReplyLoading = false;
        hasReplyMore = true;
        replyPage = 1;
     }

    document.querySelector(".reply-close").onclick = ()=>{
    modalOverlay.classList.add("hide");
    document.body.style.overflow = "auto";
    isReplyLoading = false;
    hasReplyMore = true;
    replyPage = 1;

    // 移除滚动监听
    const replyContent = document.querySelector(".reply-content");
    if (replyContent && replyContent._scrollHandler) {
        replyContent.removeEventListener('scroll', replyContent._scrollHandler);
        delete replyContent._scrollHandler;
    }
}




    document.querySelector(".replybg").onclick = (e) => {
        e.stopPropagation();
    };


    clickE(document.querySelector(".reply-content"));


    let replyJson = getJson(replyapi,2);
    let html = createHtml(replyJson.list,"comment");
    document.querySelector(".reply-content").scrollTop = 0;
    document.querySelector(".reply-content").innerHTML = html;

    const replyContent = document.querySelector(".reply-content");

    document.querySelector(".reply-pre").onclick = ()=>{
        replyContent.scrollTop = 0;
     }

    document.querySelector(".reply-next").onclick = ()=>{
        if (!(replyPage > Math.ceil((pageTotal/20))) ) {
           loadNextPage(1)
        }
        replyContent.scrollTop = replyContent.scrollHeight
     }

    // 先移除旧的监听器（防止重复绑定）
    if (replyContent._scrollHandler) {
        replyContent.removeEventListener('scroll', replyContent._scrollHandler);
    }

    replyContent._scrollHandler = function() {
    if (this.scrollTop + this.clientHeight >= this.scrollHeight - 30) {
        if (!(replyPage > Math.ceil((pageTotal/20))) ) {
            loadNextPage(1); 
        }
    }
};

    // 绑定事件
    replyContent.addEventListener('scroll', replyContent._scrollHandler);
}





function getJson(url,t,upmid){
    let commentList = [];
    let r = {};
    let allReplys = [];
    if(t==1){
        allReplys  = url;
    }else{
        let data = String(java.ajax(url));
        let JsonData = JSON.parse(data || "{}");
        data = JsonData.data;
        upmid = data.upper.mid;
        if(t!==2)
        offset = data.cursor.pagination_reply.next_offset;


        if(data.root && replyPage ==1){
            data.top_replies = [];
            data.root.rcount = 0;
            pageTotal = data.page.count;
            data.top_replies.push(data.root)
        }

        r.commentTotal = data?.cursor?.all_count;
        allReplys = data.top_replies?data.top_replies.concat(data.replies):data.replies;
    }


    for(i in allReplys){
        let x = allReplys[i];
        let comment = {};

        comment.meta =  x.reply_control.time_desc+(x.reply_control.up_reply?"•UP主回复":"");

        comment.content = parseContent(x.content.message,x.content.pictures,x.content.emote,x.content.at_name_to_mid,x.content.jump_url);
        comment.username = x.member.uname;
        comment.agreenum = x.like;
        let top = x.reply_control.is_up_top?"置顶":""
        if(top)comment.top = top;
        comment.authorid = upmid;
        comment.isAuthor = x.member.mid==upmid;
        comment.readerid = x.member.mid;
        comment.icon = x.member.nameplate.image ?? "";
        comment.rate = "LV"+x.member.level_info.current_level;
        comment.replyNum = Number(x.rcount) ?? 0;
        comment.id = x.rpid;
        comment.author_agree= x.reply_control.up_like;
        if(comment.replyNum>0){
            comment.list = x.replies?getJson(x.replies,1,upmid):[];
        }
        commentList.push(comment)
    }

    if(t==1)return commentList;

    r.list = commentList;
    return r

}     

 function parseContent(content,pics,emo,atname,jump_url){
     if(emo){
         let emok = Object.keys(emo)
         let emok2 = emok.map(key => 
